namespace Halls.Database; public static class DotEnvReader{public static void Load(){var d=new DirectoryInfo(Directory.GetCurrentDirectory());while(d is not null){var p=Path.Combine(d.FullName,".env");if(File.Exists(p)){foreach(var l in File.ReadLines(p)){var i=l.IndexOf('=');if(i>0&&string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(l[..i].Trim())))Environment.SetEnvironmentVariable(l[..i].Trim(),l[(i+1)..].Trim());}return;}d=d.Parent;}}}
